out = {"_meta": {"batch": "batch-011", "writer": "hand-written (Claude, no API)", "judge": "self-rated by the writer"}}
for cid, cl in C.items():
    if cid not in cands: continue
    c = cands[cid]
    assert set(cl) == {e['answer'] for e in c['entries']}, (cid, set(cl) ^ {e['answer'] for e in c['entries']})
    out[cid] = {"theme": c.get('theme_hint'), "category": c.get('category', 'themed'),
                "clues": {a: {"clue": v[0], "type": v[1], "rating": v[2]} for a, v in cl.items()},
                "critique": {"notes": "Themed round."}}
missing = [c for c in cands if c not in out]
if missing: print('no clues for', missing)
json.dump(out, open('clues/batch-011.clues.json', 'w'), indent=1)
print(len(out) - 1, 'rounds')
